$('exportPng').onclick=async()=>{if(!ready)return;const btn=$('exportPng');btn.disabled=true;btn.textContent='이미지 만드는 중…';let url;try{await document.fonts.load('32px "KoPubLocal"');await document.fonts.ready;const width=exportInfo(),xml=exportXml().replace(/width="[\d.]+mm"/,'width="1000"').replace(/height="[\d.]+mm"/,`height="${H}"`);url=URL.createObjectURL(new Blob([xml],{type:'image/svg+xml;charset=utf-8'}));const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});const canvas=document.createElement('canvas');canvas.width=width;canvas.height=Math.round(width/state.ratio);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error();download(await withDpi(blob,Number($('dpi').value)),'.png');toast('출제용 고화질 PNG를 저장했습니다.')}catch{toast('이미지 저장에 실패했습니다. SVG 저장을 사용하거나 다시 시도하세요.')}finally{if(url)URL.revokeObjectURL(url);btn.disabled=false;btn.textContent='↓ PNG 이미지 저장'}};
$('saveProject').onclick=()=>{download(new Blob([JSON.stringify({format:'blank-map-studio',version:1,state},null,2)],{type:'application/json'}),'.json');toast('다시 편집할 수 있는 작업 파일을 저장했습니다.')};$('loadProject').onclick=()=>$('projectFile').click();
function validState(s){const pair=p=>Array.isArray(p)&&p.length===2&&p.every(n=>Number.isFinite(n)&&Math.abs(n)<=10000),colors=['#d5d5d5','#a9a9a9','#777777','#ffffff','hatch'];return s&&Object.hasOwn(regions,s.region)&&[1.4,1.7777778,2,1].includes(s.ratio)&&['clean','exam','contrast'].includes(s.mapStyle)&&['abc','korean','jamo','number','none'].includes(s.symbols)&&colors.includes(s.fill)&&['dashed','solid','none'].includes(s.boundary)&&['kopub','sans','serif'].includes(s.font)&&s.fontSize>=12&&s.fontSize<=80&&(s.autoAssist===undefined||['smart','arrow','ellipse','both','none'].includes(s.autoAssist))&&s.lineWidth>=.4&&s.lineWidth<=2.5&&['equator','grid','frame'].every(k=>typeof s[k]==='boolean')&&s.view&&s.view.k>=.5&&s.view.k<=15&&[s.view.x,s.view.y].every(Number.isFinite)&&Array.isArray(s.countries)&&s.countries.length<=250&&new Set(s.countries.map(c=>c.id)).size===s.countries.length&&s.countries.every(c=>features.some(f=>f.id===c.id)&&pair(c.pos)&&typeof c.text==='string'&&c.text.length<=30&&colors.includes(c.fill)&&(c.size===undefined||Number.isFinite(c.size)&&c.size>=12&&c.size<=80)&&(c.assist===undefined||['inherit','arrow','ellipse','both','none'].includes(c.assist)))&&Array.isArray(s.annotations)&&s.annotations.length<=500&&s.annotations.every(a=>typeof a.id==='string'&&!a.id.startsWith('country:')&&['label','point','line','ellipse'].includes(a.type)&&pair(a.a)&&(a.size===undefined||Number.isFinite(a.size)&&a.size>=12&&a.size<=80)&&(['label','point'].includes(a.type)?typeof a.text==='string'&&a.text.length<=30:pair(a.b)&&typeof a.dash==='boolean'))}
$('projectFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error();const d=JSON.parse(await file.text());if(d.format!=='blank-map-studio'||d.version!==1||!validState(d.state))throw Error();checkpoint();restore(JSON.stringify(d.state));toast('저장한 작업을 불러왔습니다.')}catch{toast('올바른 백지도 스튜디오 작업 파일을 선택하세요.')}finally{e.target.value=''}};
$('autoArrange').onclick=()=>{checkpoint();autoArrange();render();toast('선택한 국가의 기호와 연결 표시를 자동 배치했습니다.')};
$('fontSizeNumber').onchange=()=>{const v=Number($('fontSizeNumber').value);if(!Number.isFinite(v)||v<12||v>80){$('fontSizeNumber').value=state.fontSize;return}$('fontSize').value=v;$('fontSize').dispatchEvent(new Event('change'))};
$('itemSize').onchange=()=>{const a=getActive(),v=Number($('itemSize').value);if(!a)return;if(!Number.isFinite(v)||v<12||v>80){$('itemSize').value=a.size||state.fontSize;return}checkpoint();a.size=v;render()};
$('resetItemSize').onclick=()=>{const a=getActive();if(a){checkpoint();delete a.size;render()}};
$('itemAssist').onchange=()=>{const a=getActive();if(a&&active?.startsWith('country:')){checkpoint();a.assist=$('itemAssist').value;autoPlaceCountry(a);render()}};
async function init(){try{const results=await Promise.all([fetch('data/countries.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('data/land.json').then(r=>{if(!r.ok)throw Error();return r.json()})]);features=results[0].features;land=results[1];ready=true;$('loading').remove();example(true);updateUndo()}catch{$('loading').textContent='지도를 불러오지 못했습니다. 새로고침해 다시 시도하세요.';toast('지도 자료를 불러오지 못했습니다.')}}init();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'read_blank_map',description:'현재 백지도의 지역과 선택 국가·기호를 읽습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){if(!ready)throw Error('지도를 불러오는 중입니다.');return{region:state.region,countries:state.countries.map(c=>({code:c.id,symbol:c.text})),annotations:state.annotations.length}}});register({name:'configure_blank_map',description:'지역과 국가 목록을 설정해 출제용 지도를 편집합니다. 지정한 국가 목록이 현재 목록을 대체하며 되돌릴 수 있습니다.',inputSchema:{type:'object',properties:{region:{type:'string',enum:Object.keys(regions)},countries:{type:'array',items:{type:'string'},maxItems:250},symbols:{type:'string',enum:['abc','korean','jamo','number','none']}},required:['region','countries','symbols'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!ready)throw Error('지도를 불러오는 중입니다.');if(!input||!Object.hasOwn(regions,input.region)||!Array.isArray(input.countries)||input.countries.length>250||!input.countries.every(id=>features.some(f=>f.id===id))||!['abc','korean','jamo','number','none'].includes(input.symbols))throw Error('지역·국가 코드·기호 형식이 올바르지 않습니다.');checkpoint();state.region=input.region;state.symbols=input.symbols;state.countries=[...new Set(input.countries)].map((id,i)=>{const f=features.find(f=>f.id===id);return{id,text:symbol(i),fill:state.fill,pos:[f.properties.LABEL_X,f.properties.LABEL_Y]}});state.view={k:1,x:0,y:0};active=null;syncControls();setup();autoArrange();renderCountries();render();return{region:state.region,selected:state.countries.length}}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
